const db = require('better-sqlite3')('/workspace/world.db');

// 1. Check rt_variants for the mouse
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-FA0948'\").all();
console.log('=== RT_VARIANTS for PROD-FA0948 ===');
console.log(JSON.stringify(variants, null, 2));

// 2. Get details of PROD-73FAB4 (Aurora Smart Desk Lamp Pro)
const lamp = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE product_id = 'PROD-73FAB4'\").get();
console.log('\n=== PROD-73FAB4 (Lamp) ===');
console.log(JSON.stringify(lamp, null, 2));

// 3. Get active electronics promotions
const promos = db.prepare(\"SELECT * FROM promotions WHERE active = 1\").all();
console.log('\n=== ACTIVE PROMOTIONS ===');
console.log(JSON.stringify(promos, null, 2));

// 4. Specifically check ELEC15
const elec15 = db.prepare(\"SELECT * FROM promotions WHERE promo_code = 'ELEC15'\").get();
console.log('\n=== ELEC15 PROMO ===');
console.log(JSON.stringify(elec15, null, 2));

// 5. Users (check for account info)
const users = db.prepare(\"SELECT user_id, name, email, loyalty_tier, loyalty_points, store_credit_balance, preferred_refund_method, is_first_time, has_prime_shipping FROM users\").all();
console.log('\n=== USERS ===');
console.log(JSON.stringify(users, null, 2));
"

